/* --------- 著作 —— 书册式 --------- */
#books{margin-top:30px;display:grid;grid-template-columns:1fr;gap:14px;}
.book{
  display:flex;align-items:center;gap:22px;padding:18px 22px;
  background:linear-gradient(90deg,var(--paper-deep),var(--paper));
  border:1px solid var(--line);position:relative;overflow:hidden;
  transition:transform .4s,box-shadow .4s,border-color .4s;
}
.book::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:var(--accent);}
.book:hover{transform:translateX(8px);border-color:var(--gold);box-shadow:6px 8px 20px rgba(27,20,12,.10);}
.book .book-yr{font-size:34px;font-weight:700;color:var(--gold);letter-spacing:.05em;min-width:110px;line-height:1;}
.book .book-t{flex:1;}
.book .book-tt{font-size:22px;font-weight:600;letter-spacing:.08em;color:var(--ink);}
.book .book-d{color:var(--ink-soft);font-size:14px;margin-top:4px;}

/* --------- 纪念 —— 页签/卡片 --------- */
#cards{margin-top:30px;display:grid;grid-template-columns:repeat(2,1fr);gap:22px;}
.card{
  padding:26px 26px 22px;border:1px solid var(--line);background:rgba(244,236,219,.6);
  position:relative;border-top:3px solid var(--accent);
  transition:transform .4s,background .4s;
}
.card.r{transform:translateY(26px);border-top-color:var(--gold);}
.card:hover{background:var(--paper-deep);transform:translateY(18px);}
.card.r:hover{transform:translateY(40px);}
.card .card-q{font-size:17px;line-height:2.1;letter-spacing:.05em;}
.card .card-src{text-align:right;color:var(--ink-soft);font-size:13px;margin-top:14px;letter-spacing:.1em;}

@media(max-width:720px){
  #cards{grid-template-columns:1fr;}
  .card.r{transform:none;}.card.r:hover{transform:none;}
  .cover .frame{padding:28px 26px;}
  header.masthead h1{display:none;}
  .quote .col{font-size:16px;}
}
